mod solution;

fn main() {
    let cases = [
    (r#"[eat,tea,tan,ate,nat]"#, r#"3"#),
    (r#"[abc,bca,foo]"#, r#"2"#),
    (r#"
[abc,bca,foo]
"#, r#"2"#),
    (r#"  
[eat,tea,tan,ate,nat]
  "#, r#"3"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS group-by-key");
}
